/* @lc app=leetcode id=2906 lang=kotlin */ class Solution { fun constructProductMatrix(grid: Array<IntArray>): Array<IntArray> = grid.flatMap { it.toList() }.let { f -> f.runningFold(1L) { p, x -> p * x % 12345 }.let { pre -> f.reversed().runningFold(1L) { p, x -> p * x % 12345 }.reversed().let { suf -> grid[0].size.let { m -> Array(grid.size) { i -> IntArray(m) { j -> (pre[i * m + j] * suf[i * m + j + 1] % 12345).toInt() } } } } } } }